function enrichBlockedProperty(key,section,related){
  const article=window.deepArticles[key];if(!article)return;
  article.sections=article.sections||[];if(!article.sections.some(item=>item.id===section.id))article.sections.push(section);
  article.related=article.related||[];for(const item of related)if(!article.related.some(existing=>existing.href===item.href))article.related.push(item);
}

enrichBlockedProperty("adam-opel-ag",{id:"blocked-doctrine",title:"Place in the blocked-property system",html:"<p>Opel became the largest public example of the <a href='blocked-property-doctrine.html'>blocked property doctrine</a>: General Motors retained title and a negotiated claim while German trustees controlled board votes, production, exports, reinvestment, dividends, and plant closure.</p>"},[{href:"blocked-property-doctrine.html",kicker:"Common legal framework",label:"Blocked Property Doctrine"},{href:"german-foreign-property-custodianship.html",kicker:"National regime",label:"German Foreign-Property Custodianship"}]);
enrichBlockedProperty("ford-werke",{id:"blocked-doctrine",title:"Place in the blocked-property system",html:"<p>Ford-Werke remained American-owned in title but German-controlled in operation under the <a href='blocked-property-doctrine.html'>blocked property doctrine</a>. Technical exchange with Ford required licenses rather than ordinary parent-company direction.</p>"},[{href:"blocked-property-doctrine.html",kicker:"Common legal framework",label:"Blocked Property Doctrine"},{href:"german-foreign-property-custodianship.html",kicker:"National regime",label:"German Foreign-Property Custodianship"}]);
enrichBlockedProperty("c-lorenz-ag",{id:"blocked-doctrine",title:"Communications as blocked property",html:"<p>C. Lorenz showed why foreign equity could not imply foreign command of radio, navigation, switching, or defense electronics. ITT's claim survived beneath German trusteeship and controlled licensing.</p>"},[{href:"blocked-property-doctrine.html",kicker:"Common legal framework",label:"Blocked Property Doctrine"},{href:"german-foreign-property-custodianship.html",kicker:"National regime",label:"German Foreign-Property Custodianship"}]);
enrichBlockedProperty("ibm",{id:"dehomag-claim",title:"The Dehomag claim",html:"<p>IBM's German subsidiary <a href='dehomag.html'>Dehomag</a> remained under German custodians after 1947. IBM retained claims to shares, patents, marks, and technical exchange but did not control German government and industrial data processing.</p>"},[{href:"dehomag.html",kicker:"Blocked German subsidiary",label:"Dehomag"},{href:"blocked-property-doctrine.html",kicker:"International framework",label:"Blocked Property Doctrine"}]);
enrichBlockedProperty("german-imperial-monetary-system",{id:"blocked-foreign-accounts",title:"Blocked foreign accounts",html:"<p>Foreign dividends and claims accumulated inside controlled Reichsmark accounts. Bilateral commissions converted selected balances into reinvestment, approved imports, bonds, licenses, or reciprocal releases under the <a href='blocked-property-doctrine.html'>blocked property doctrine</a>.</p>"},[{href:"blocked-property-doctrine.html",kicker:"Foreign property rule",label:"Blocked Property Doctrine"},{href:"transbloc-industrial-claims-conferences.html",kicker:"Settlement machinery",label:"Claims Conferences"}]);
enrichBlockedProperty("japanese-imperial-economic-system",{id:"foreign-property",title:"Captured and blocked foreign property",html:"<p>British, Dutch, and American banks, oil groups, plantations, merchant houses, and industrial branches entered <a href='japanese-foreign-property-custodianship.html'>Japanese custody</a> during conquest. Later treaties protected Japanese operating rights while old parents pursued compensation, licenses, or minority claims rather than colonial restoration.</p>"},[{href:"japanese-foreign-property-custodianship.html",kicker:"Property regime",label:"Japanese Foreign-Property Custodianship"},{href:"blocked-property-doctrine.html",kicker:"Comparative doctrine",label:"Blocked Property Doctrine"}]);
enrichBlockedProperty("transfer-east-indian-commanding-assets",{id:"foreign-claimants",title:"The displaced corporate claimants",html:"<p><a href='royal-dutch-shell.html'>Royal Dutch Shell</a>, <a href='standard-vacuum-oil.html'>Standard-Vacuum</a>, <a href='unilever.html'>Unilever</a>, banks, and merchant houses survived outside the occupied estate. Their continuing claims did not reverse the transfer of fields, plantations, refineries, mills, warehouses, and trading networks to Japanese operators.</p>"},[{href:"japanese-foreign-property-custodianship.html",kicker:"Legal framework",label:"Japanese Foreign-Property Custodianship"},{href:"royal-dutch-shell.html",kicker:"Oil claimant",label:"Royal Dutch Shell"}]);
enrichBlockedProperty("southern-archipelago-concession-system",{id:"former-owners",title:"Former owners and residual claims",html:"<p>Prewar European and American parents retained external claims against assets now governed by Japanese concessions. Claims settlements could create compensation, licenses, or minority participation, but they did not invalidate the successor states' postwar economic constitution.</p>"},[{href:"japanese-foreign-property-custodianship.html",kicker:"Predecessor property regime",label:"Japanese Foreign-Property Custodianship"},{href:"transbloc-industrial-claims-conferences.html",kicker:"External claims",label:"Claims Conferences"}]);
enrichBlockedProperty("singapore",{id:"displaced-british-finance",title:"Displaced British banks and merchant houses",html:"<p>The new clearing center absorbed functions once performed by British institutions such as <a href='hongkong-shanghai-banking-corporation.html'>HSBC</a> and merchant houses such as <a href='jardine-matheson.html'>Jardine Matheson</a>. Later foreign offices operated beneath Singaporean and Japanese rules rather than recovered colonial privilege.</p>"},[{href:"hongkong-shanghai-banking-corporation.html",kicker:"Displaced bank",label:"Hongkong and Shanghai Banking Corporation"},{href:"jardine-matheson.html",kicker:"Displaced merchant house",label:"Jardine Matheson"}]);
